    "short": "春秋时期齐国名相，辅佐齐桓公成为春秋五霸之首，推行改革，富国强兵。",
    "intro": "管仲，字夷吾，颍上人。据《史记·管晏列传》，管仲少时贫困，与鲍叔牙经商。后辅佐齐公子纠，公子纠与公子小白争位，小白胜，是为齐桓公。鲍叔牙荐管仲于桓公，桓公以管仲为相。管仲推行改革，设乡闾、制国野、通商工之业、便鱼盐之利，齐国大治。辅佐齐桓公九合诸侯，一匡天下，成为春秋五霸之首。",
