    "short": "春秋时期齐国名相，历仕齐灵公、庄公、景公三朝，以节俭力行、机智善辩著称。",
    "intro": "晏婴，字仲，夷维人。据《史记·管晏列传》，晏婴事齐灵公、庄公、景公，以节俭力行重于齐。既相齐，食不重肉，妾不衣帛。晏婴机智善辩，出使楚国，以智挫败楚王的羞辱。晏子使楚，楚王以晏子短，为小门于大门之侧而延晏子。晏子不入，曰：「使狗国者，从狗门入。」楚王曰：「齐无人耶？」晏子对曰：「齐之临淄三百闾，张袂成阴，挥汗成雨，比肩继踵而在，何为无人！」",
