    "intro": "周文王，姬姓，名昌，商末周部落首领。据《史记·周本纪》，文王遵后稷、公刘之业，则古公、公季之法，笃仁，敬老，慈少。礼下贤者，日中不暇食以待士，士以此多归之。商纣囚文王于羑里，文王演《周易》之八卦为六十四卦。诸侯闻之，皆曰「西伯盖受命之君」。文王卒后，武王继位，遂伐纣。",
