    "short": "周朝开国君主，继承文王遗志，率诸侯伐纣，牧野之战击败商军，建立周朝。",
    "intro": "周武王，姬姓，名发，文王之子。据《史记·周本纪》，文王崩，太子发立，是为武王。武王继位后，率诸侯伐纣。纣亦发兵距之牧野。纣师虽众，皆无战心，欲武王亟入。纣师皆倒兵以战，以开武王。武王驰之，纣兵皆崩畔纣。纣走，反入朝歌，自焚于鹿台。武王遂定天下，定都镐京，国号周。",
