    "intro": "商汤，子姓，名履，商部落首领。据《史记·殷本纪》，夏桀无道，汤修德，诸侯皆归汤。汤率诸侯伐桀，战于鸣条，桀败走，死于南巢。汤遂即天子位，定都于亳，国号商。汤以宽治民，轻徭薄赋，百姓亲附。",
