    "intro": "孟尝君，名文，齐威王少子田婴之子。据《史记·孟尝君列传》，田文承袭父爵于薛，号孟尝君。孟尝君在薛，招致诸侯宾客及亡人有罪者，皆归孟尝君。孟尝君舍业厚遇之，以故倾天下之士。食客数千人，无贵贱一与文等。孟尝君曾入秦为相，后被秦昭王囚禁，靠门客「鸡鸣狗盗」之术逃归。后齐湣王以为齐相，西合于秦、赵，与魏共伐秦。",
