    "intro": "汉武帝，名彻，汉景帝之子，王美人之子。据《史记·孝武本纪》，武帝七岁为太子，十六岁即位。在位期间，采纳董仲舒建议，罢黜百家，独尊儒术。派遣卫青、霍去病多次北击匈奴，收复河套地区，打通河西走廊。派遣张骞出使西域，开辟丝绸之路。盐铁官营，统一货币。但晚年穷兵黩武，巫蛊之祸逼死太子刘据。",
    "achievements": [
      "罢黜百家，独尊儒术，确立儒家正统地位",
      "派遣卫青、霍去病北击匈奴，收复河套",
      "派遣张骞出使西域，开辟丝绸之路",
      "开通西南夷，平定南越、东越",
      "推行盐铁官营，统一货币（五铢钱）"
    ],
    "controversy": "晚年穷兵黩武，国库空虚；巫蛊之祸逼死太子刘据；迷信方术，求仙问道。",
    "quote": "犯强汉者，虽远必诛。",
    "quoteSrc": "《汉书·陈汤传》",
