    "intro": "卫青，字仲卿，河东平阳人。据《史记·卫将军骠骑列传》，卫青出身卑微，少时为平阳侯家骑奴。其姊卫子夫得幸于武帝，卫青因此入宫。后击匈奴有功，拜为大将军，封长平侯。卫青一生七次出击匈奴，收复河套地区，设朔方郡，解除了匈奴对长安的直接威胁。卫青为人仁善退让，以和柔自媚于上，然天下未有称也。",
