    "intro": "秦二世，名胡亥，秦始皇第十八子。据《史记·秦始皇本纪》，始皇崩于沙丘，赵高与李斯矫诏，废太子扶苏，立胡亥为二世皇帝。胡亥即位后，听信赵高，诛杀兄弟大臣，大兴土木，民怨沸腾。陈胜吴广起义后，赵高恐罪及己，乃与其婿阎乐逼二世自杀。",
