    "controversy": "项羽坑杀秦降卒二十万、火烧咸阳阿房宫，暴虐残忍。鸿门宴不杀刘邦，被后世视为重大失误。",
    "quote": "力拔山兮气盖世，时不利兮骓不逝。骓不逝兮可奈何，虞兮虞兮奈若何！",
