    "intro": "刘邦，字季，沛县丰邑人。据《史记·高祖本纪》，刘邦为人，仁而爱人，喜施，意豁如也。常有大度，不事家人生产作业。秦末起义，刘邦斩白蛇起兵，先入关中，秦王子婴投降。后与项羽争夺天下，楚汉战争四年，最终击败项羽，建立汉朝，定都长安。刘邦在位期间，休养生息，轻徭薄赋，奠定汉朝四百年基业。",
