    "short": "西汉权臣，霍去病之弟。昭帝死后，废昌邑王刘贺，立宣帝，执政二十年，权倾天下。",
    "intro": "霍光者，字子孟，河东平阳人也。据《汉书·霍光传》，光为骠骑将军霍去病弟。去病死后，光为奉车都尉、光禄大夫，出则奉车，入侍左右，出入禁闼二十馀年，小心谨慎，未尝有过，甚见亲信。征和二年，卫太子为江充所败，而燕王旦、广陵王胥皆多过失。是时上年老，宠姬钩弋赵倢伃有男，上心欲以为嗣，命大臣辅之。察群臣唯光任大重，可属社稷。上乃使黄门画者画周公负成王朝诸侯以赐光。后元二年春，上游五柞宫，病笃，光涕泣问曰：「如有不讳，谁当嗣者？」上曰：「君未谕前画意邪？立少子，君行周公之事。」光顿首让曰：「臣不如金日磾。」日磾亦曰：「臣外国人，不如光。」上以光为大司马大将军，日磾为车骑将军，及太仆上官桀为左将军，搜粟都尉桑弘羊为御史大夫，皆拜卧内床下，受遗诏辅少主。明日，武帝崩，太子袭尊号，是为孝昭皇帝。帝年八岁，政事壹决于光。光为人沉静详审，长财七尺三寸，白皙，疏眉目，美须髯。每出入下殿门，止进有常处，郎仆射窃识视之，不失尺寸，其资性端正如此。初辅幼主，政自己出，天下想闻其风采。殿中尝有怪，一夜群臣相惊，光召尚符玺郎，郎不肯授光。光欲夺之，郎按剑曰：「臣头可得，玺不可得也！」光甚谊之。明日，诏增此郎秩二等。众庶莫不多光。",
