    "placeId": "jiuzhou",
    "short": "大禹受命治水，十三年劳身焦思，三过家门而不入，终开九州、通九道、陂九泽、度九山。",
    "bg": "尧时洪水滔天，命鲧治水。鲧用堵截之法，九年无功。舜流放鲧于羽山，命禹继父业治水。",
    "process": "禹改用疏导之法，陆行乘车，水行乘船，泥行乘橇，山行乘檋。左准绳，右规矩，载四时，以开九州，通九道，陂九泽，度九山。十三年间三过家门而不入。",
    "result": "洪水平定，九州划定，天下大治。禹以此功德受舜禅让，建立夏朝。",
    "controversy": "禹治水范围与具体路径，学界有不同看法。禹贡九州是否为禹时所划定，亦有争议。",
