    "bg": "汉初经历秦末战乱与楚汉战争，经济凋敝，民生困苦。文帝、景帝继位后，推行黄老之术，与民休息。",
    "process": "文帝即位后，躬修节俭，废除肉刑，田租三十税一。景帝继续推行，平定七国之乱，削弱诸侯。两代皇帝统治四十余年，社会经济恢复，府库充盈。",
    "result": "社会经济恢复，人口大增，国库充盈。到武帝初年，天下殷富，粟至十余钱，为汉武帝对外扩张奠定物质基础。",
